-- ═══════════════════════════════════════════════════════════════
-- NeuCore — Phase 13: System Exercise Library (David Grey import)
-- Idempotent. Rollback: rollbacks/20260619000000_system_exercise_library_down.sql
--
-- Additive only. System exercises = created_by IS NULL + is_global = true,
-- which the Phase 5 RLS (exercises_select) already exposes to all coaches
-- read-only, hides from client browsing, and lets clients see ONLY exercises
-- referenced in their own published program. No policy changes here.
--
-- 152 exercises extracted from 4 David Grey PDFs via PDF link annotations.
-- Provenance columns are nullable (coach-private rows leave them NULL).
-- Re-running this migration upserts on source_key → no duplicates.
-- ═══════════════════════════════════════════════════════════════

-- ── 0. Extend the category grouping to include body regions ──
-- Existing values (rehab modalities) stay valid; David Grey system exercises
-- group by body region. NULL stays allowed. Coach-created exercises are
-- unaffected (the create form still offers the modality values).
alter table public.exercises drop constraint if exists exercises_category_check;
alter table public.exercises add constraint exercises_category_check
  check (category is null or category = any (array[
    'Rehab','Mobility','Strength','Neurology','Breathing',
    'Upper Body','Core','Lower Body']));

-- ── 1. Additive provenance columns + idempotency key ──
alter table public.exercises
  add column if not exists source_key     text,
  add column if not exists source_file    text,
  add column if not exists source_program text,
  add column if not exists source_section text;

-- NULLs are distinct in Postgres unique indexes, so coach-private rows
-- (source_key NULL) are unaffected; only the imported system rows are keyed.
create unique index if not exists exercises_source_key_uniq
  on public.exercises (source_key);

-- ── 2. Idempotent upsert of the system library ──
